using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using MaritimeLegend.Domain;
namespace MaritimeLegend.Editor {
public static class DomainChecks {
static List<string> lines; static int count;
static void Check(bool ok,string name){if(!ok)throw new Exception("TEST FAILED: "+name);lines.Add("PASS "+name);count++;}
[MenuItem("Maritime Legend/Run domain checks")]
public static void Run(){lines=new List<string>();count=0;var c=JsonUtility.FromJson<Catalog>(Resources.Load<TextAsset>("Data/catalog").text);c.Validate();Check(c.products.Length==50,"50 products including flagship instrument; 49 entries in requested table");Check(c.ports.Length==8&&c.partners.Length==12&&c.recipes.Length==33,"8 ports / 12 partners / 33 closed recipes");foreach(var p in c.products.Where(x=>x.category=="R"))Check(c.ports.Count(x=>x.raw.Contains(p.id))>=2,"dual supply "+p.name);
var s=GameService.New(c,0,0,"休闲",new Appearance(),"Test",71527);s.gold=1500;var g=new GameService(c,s);string timber=c.Named("原木").id;s.eventFlags.Add("e1");int before=s.gold;int quote=g.Quote(0,timber,3,true);g.Trade(0,timber,3,40,true,s.cargo);Check(g.Quote(0,timber,3,true)>quote,"large buy raises price");double pressure=g.Market(0,timber).pressure;g.Trade(0,timber,3,40,false,s.cargo);Check(g.Market(0,timber).pressure<pressure,"large sell lowers price");Check(s.gold<=before,"same-city round trip after spread has no profit");var json=JsonUtility.ToJson(s);g.Trade(0,timber,3,999,true,s.cargo);Check(json==JsonUtility.ToJson(s),"failed transaction atomically unchanged");
for(int h=0;h<30*24;h++){g.MarketHour();foreach(var cs in s.cities)foreach(var m in cs.market)if(m.stock<0||m.stock>c.market.maxStock)throw new Exception("NPC bounds");}Check(true,"30 game days / 720 NPC hourly replenishment cycles; stocks bounded");Check(g.Quote(0,timber,3,true)<g.Quote(3,timber,3,false),"cross-port raw trade has positive gross margin");
uint seed=778899;var roller=new QualityRoller();for(int worst=0;worst<=5;worst++)for(int sample=0;sample<1000;sample++){int q=roller.Roll(worst,20,0,ref seed);if(q<0||q>worst)throw new Exception("quality bound for all six input grades");}Check(true,"all six input grades preserve quality boundary");int low=0,high=0,sl=0,sh=0;for(int i=0;i<200000;i++){int a=roller.Roll(3,1,0,ref seed),b=roller.Roll(3,20,0,ref seed);if(a<0||a>3||b<0||b>3)throw new Exception("quality boundary");if(a<3)low++;if(b<3)high++;if(a==0)sl++;if(b==0)sh++;}Check(high>low&&sh>sl,"400000 quality samples: higher skill improves quality and S remains bounded");lines.Add("Quality improvements: level1="+low+", level20="+high+"; S level1="+sl+", level20="+sh);
s.cities[0].factories[3]=1;g.Inventory.Add(s.cities[0].warehouse,timber,3,20,0);var recipe=c.recipes.First(x=>x.output==c.Named("木板").id);int orderCount=s.orders.Count;g.Start(recipe.id,0);Check(s.orders.Count==orderCount+1,"production consumes and locks materials");var o=s.orders.Last();int originalQuality=o.quality;g.Advance(2,false);double first=o.progress;s.city=1;g.Advance(10,false);Check(o.progress>first&&o.progress<.8,"city switch accumulates progress without reset and uses slow tier");double away=o.progress;g.Advance(3600,true);Check(o.progress>away,"offline tier progresses same order");string serialized=JsonUtility.ToJson(s);var loaded=JsonUtility.FromJson<GameState>(serialized);Check(loaded.orders.Last().quality==originalQuality,"order quality survives serialization unchanged");g.Advance(10000,true);Check(o.completed,"offline order completes");g.Claim(o.id);int owned=g.Inventory.Count(s.cities[0].warehouse,recipe.output);g.Claim(o.id);Check(g.Inventory.Count(s.cities[0].warehouse,recipe.output)==owned,"claim idempotent");s.lastUtc=DateTime.UtcNow.AddHours(2).ToString("O");g.RecoverOffline(DateTime.UtcNow);Check(s.journal[0].Contains("时钟"),"backwards clock logged and clamped");
var fresh=GameService.New(c,0,0,"经典",new Appearance(),"Route test",912);var service=new GameService(c,fresh);string response=service.AddAuto(1,timber,3,999,1);Check(fresh.autoRoutes.Count==0&&response.Contains("发现"),"automatic transport requires discovered directed route");Sail(service,1);Check(fresh.routes.Contains("0>1")&&!fresh.atSea,"manual sailing simulation discovers directed route");fresh.gold=20000;service.BuyShip(1);fresh.city=0;service.AddAuto(1,timber,3,999,1);service.Tick(1,false);service.Tick(65,false);Check(fresh.autoRoutes.Count==1&&fresh.autoRoutes[0].status=="完成"&&fresh.autoRoutes[0].profit>0,"automatic transport moves real inventory and realizes profit");
var eventState=GameService.New(c,3,0,"休闲",new Appearance(),"Events",123);eventState.gold=1500;var eventService=new GameService(c,eventState);eventService.ChooseEvent(true);Check(eventState.gold==1480&&eventState.cities[0].reputation==5,"event support choice consumes money and grants reputation");eventService.Emit("home");Check(eventState.pendingEvents.Count==0,"one-shot event deduplication");foreach(string mode in new[]{"休闲","经典"})Campaign(c,mode);
SaveStore.TestDirectory=Path.GetFullPath("Temp/MaritimeTests/Saves");SaveStore.Save(s);var disk=SaveStore.Load(s.slot);Check(disk.orders.Last().quality==s.orders.Last().quality&&disk.gold==s.gold,"disk save hash and state roundtrip");SaveStore.Save(s);string path=SaveStore.PathFor(s.slot);File.WriteAllText(path,File.ReadAllText(path).Replace("\"hash\":\"","\"hash\":\"damaged"));bool refused=false;try{SaveStore.Load(s.slot);}catch{refused=true;}Check(refused,"corrupt save rejected without reset");Check(SaveStore.Load(s.slot,false,true).gold==s.gold,"backup recovery preserves state");SaveStore.TestDirectory=null;
Directory.CreateDirectory("Documentation");File.WriteAllLines("Documentation/TestResults.txt",lines.Concat(new[]{"TOTAL "+count+" checks passed", "These are deterministic rule simulations, not manual full UI acceptance or audio listening."}));Debug.Log("MARITIME_DOMAIN_TESTS_PASS "+count);
}
static void Sail(GameService g,int to){string msg=g.Depart(to);if(!g.S.atSea)throw new Exception(msg);int steps=0;while(g.DistanceToPort()>.025&&steps++<10000){var p=g.C.ports[to];g.S.heading=Math.Atan2(p.y-g.S.seaY,p.x-g.S.seaX);g.Sail(.1,1);g.Tick(.1,false);}if(steps>=10000)throw new Exception("sailing timeout");g.Arrive();}
static void Campaign(Catalog c,string mode){var s=GameService.New(c,5,0,mode,new Appearance(),"Campaign",37812);s.gold=1500;var g=new GameService(c,s);string wood=c.Named("原木").id;g.Trade(0,wood,3,10,true,s.cargo);g.Build(3);g.Inventory.Transfer(s.cargo,s.cities[0].warehouse,wood,3,10);g.Start("r"+c.Named("木板").id,0);g.Advance(60,false);g.Claim(s.orders.Last().id);Sail(g,1);Check(s.chapter==2,mode+" campaign chapter1 reached using production/trade/sailing");g.License();for(int i=0;i<6;i++){g.Trade(1,c.Named("小麦").id,3,1,true,s.cargo);}Sail(g,0);g.Recruit(0);
// Earn expedition funds through bounded raw cargo transfers, no money injection.
for(int loop=0;loop<100&&s.gold<24000;loop++){int n=Math.Min(30,Math.Max(1,(s.gold-100)/80));var export=c.ports[0].raw.OrderByDescending(id=>g.Preview(3,id,3,n,false)-g.Preview(0,id,3,n,true)).First();if(g.Preview(3,export,3,n,false)<=g.Preview(0,export,3,n,true)){for(int h=0;h<48;h++)g.MarketHour();continue;}int previousGold=s.gold;g.Trade(0,export,3,n,true,s.cargo);Sail(g,3);g.Trade(3,export,3,n,false,s.cargo);if(!s.cities[3].license&&s.gold>550)g.License();Sail(g,0);g.Supply();for(int h=0;h<48;h++)g.MarketHour();}lines.Add(mode+" campaign earned gold through adaptive raw trading: "+s.gold);

for(int i=0;i<2;i++){g.Start("r"+c.Named("木板").id,0);g.Advance(60,false);g.Claim(s.orders.Last().id);}g.CheckQuest();Check(s.chapter==3,mode+" campaign chapter2 reached with three licensed cities and partner");g.TrainPartner(0);g.BuyShip(1);Check(s.ships.Count>1,mode+" campaign can afford trade brig");g.Flagship(1);
// Craft terminal goods with genuinely purchased materials; all quality rolls use persisted PRNG.
EnsureFactory(g,3);CraftQuality(g,"木板",2);MoveOne(g,"木板",2);Sail(g,1);EnsureFactory(g,2);CraftQuality(g,"布匹",2);MoveOne(g,"布匹",2);Check(g.SubmitMaterials().Contains("已登记"),mode+" distinct-port quality materials accepted");EnsureFactory(g,5);CraftQuality(g,"旗舰航海仪",2);EnsureFactory(g,2);CraftQuality(g,"船帆",5);Check(s.instrumentMade&&s.sailsMade,mode+" campaign terminal manufactured goods reachable");Check(g.BeginFinal().Contains("解缆"),mode+" final gate satisfied");int steps=0;while(g.DistanceToPort()>.025&&steps++<10000){var p=c.ports[7];s.heading=Math.Atan2(p.y-s.seaY,p.x-s.seaX);g.Sail(.1,1);g.Tick(.1,false);}g.Arrive();Check(s.city==7&&s.ships[0].food>5&&s.ships[0].hull>10,mode+" final voyage arrives with supplies");if(mode=="休闲"){g.Finish();Check(s.ended,"casual ending state and postgame unlocked");int reward=s.gold;g.Finish();Check(s.gold==reward,"ending reward cannot be claimed twice");}else lines.Add("CLASSIC: final battle UI still requires runtime combat acceptance; campaign gates tested only.");}
static void EnsureFactory(GameService g,int industry){if(g.S.cities[g.S.city].factories[industry]==0){string msg=g.Build(industry);if(g.S.cities[g.S.city].factories[industry]==0)throw new Exception("Factory "+msg);}}
static void CraftQuality(GameService g,string name,int maximum){var p=g.C.Named(name);var r=g.C.recipes.First(x=>x.output==p.id);EnsureFactory(g,r.industry);for(int attempt=0;attempt<100;attempt++){foreach(var input in r.inputs){int need=input.quantity-g.Inventory.Count(g.S.cities[g.S.city].warehouse,input.product);if(need>0){var prod=g.C.Product(input.product);if(g.Market(g.S.city,prod.id).stock<need){if(prod.category=="R"){int port=g.C.ports.First(x=>x.raw.Contains(prod.id)).id;int home=g.S.city;Sail(g,port);g.Trade(port,prod.id,3,need,true,g.S.cargo);Sail(g,home);g.Inventory.Transfer(g.S.cargo,g.S.cities[home].warehouse,prod.id,3,need);}else CraftQuality(g,prod.name,5);}else g.Trade(g.S.city,prod.id,3,need,true,g.S.cities[g.S.city].warehouse);}}
int prev=g.S.orders.Count;string start=g.Start(r.id,g.S.city);if(g.S.orders.Count==prev)throw new Exception("Craft "+name+": "+start+" gold="+g.S.gold);g.Advance(60,false);var o=g.S.orders.Last();g.Claim(o.id);if(o.quality<=maximum)return;}throw new Exception("Quality target not reached "+name);}
static void MoveOne(GameService g,string name,int maximum){var inv=g.S.cities[g.S.city].warehouse;var b=inv.batches.First(x=>x.product==g.C.Named(name).id&&x.quality<=maximum);g.Inventory.Transfer(inv,g.S.cargo,b.product,b.quality,1);}
}}
